<?php
require __DIR__ . '/_auth.php'; exigir_admin();
require __DIR__ . '/../config/conexion.php';
try {
    $materias=bd()->query('SELECT id_materia,nombre FROM materias ORDER BY id_materia')->fetchAll();
    $lecciones=bd()->query('SELECT l.id_leccion,l.titulo,l.nivel,m.nombre AS materia FROM lecciones l JOIN materias m ON m.id_materia=l.id_materia ORDER BY l.id_leccion DESC')->fetchAll();
    $actividades=bd()->query('SELECT a.id_actividad,a.pregunta,l.titulo FROM actividades a JOIN lecciones l ON l.id_leccion=a.id_leccion ORDER BY a.id_actividad DESC')->fetchAll();
    $estadisticas=bd()->query("SELECT (SELECT COUNT(*) FROM usuarios WHERE token_acceso IS NOT NULL) AS visitantes, (SELECT COUNT(*) FROM progreso) AS intentos, (SELECT COUNT(*) FROM progreso WHERE completada=1) AS aciertos, (SELECT COALESCE(SUM(puntos_obtenidos),0) FROM progreso) AS puntos")->fetch();
} catch(Throwable $e) { http_response_code(500); exit('No se pudo consultar la base de datos'); }
$estado = $_GET['estado'] ?? '';
?>
